<?php require_once __DIR__.'/includes/bootstrap.php';require_verified();$u=current_user();$staff=in_array($u['role'],['admin','librarian'],true);$books=(int)$conn->query('SELECT COUNT(*) n FROM books WHERE is_archived=0')->fetch_assoc()['n'];$active=(int)$conn->query("SELECT COUNT(*) n FROM borrowings WHERE status IN ('pending','approved','borrowed')")->fetch_assoc()['n'];$returned=(int)$conn->query("SELECT COUNT(*) n FROM borrowings WHERE status='returned'")->fetch_assoc()['n'];$activeReservations=(int)$conn->query("SELECT COUNT(*) n FROM reservations WHERE status IN('pending','approved','ready')")->fetch_assoc()['n'];$members=(int)$conn->query("SELECT COUNT(*) n FROM users WHERE role='member'")->fetch_assoc()['n'];if($staff)$r=$conn->query('SELECT br.*,b.title,u.full_name FROM borrowings br JOIN books b ON b.id=br.book_id JOIN users u ON u.id=br.user_id ORDER BY br.id DESC LIMIT 8');else{$id=(int)$u['id'];$s=$conn->prepare('SELECT br.*,b.title FROM borrowings br JOIN books b ON b.id=br.book_id WHERE br.user_id=? ORDER BY br.id DESC LIMIT 8');$s->bind_param('i',$id);$s->execute();$r=$s->get_result();}page_header('Dashboard');?><div class="page-heading"><div><p class="eyebrow">OVERVIEW</p><h1>Hello, <?=e($u['full_name'])?> 👋</h1><p class="muted">Here is what is happening in your library.</p></div><a class="btn" href="books.php">Browse books</a></div><div class="stats"><div class="stat"><span>Book titles</span><strong><?=$books?></strong></div><div class="stat"><span>Active transactions</span><strong><?=$active?></strong></div><div class="stat"><span>Returned loans</span><strong><?=$returned?></strong></div><div class="stat"><span>Active reservations</span><strong><?=$activeReservations?></strong></div><?php if($staff):?><div class="stat"><span>Members</span><strong><?=$members?></strong></div><?php endif;?></div><section class="panel"><h2><?=$staff?'Recent borrowing activity':'My recent requests'?></h2><div class="table-wrap"><table><thead><tr><th>ID</th><?php if($staff):?><th>Member</th><?php endif;?><th>Book</th><th>Status</th><th>Requested</th></tr></thead><tbody><?php if($r->num_rows):while($x=$r->fetch_assoc()):?><tr><td>#<?=$x['id']?></td><?php if($staff):?><td><?=e($x['full_name'])?></td><?php endif;?><td><?=e($x['title'])?></td><td><?=status_badge($x['status'])?></td><td><?=e($x['requested_at'])?></td></tr><?php endwhile;else:?><tr><td colspan="5">No records yet.</td></tr><?php endif;?></tbody></table></div></section><?php page_footer();?>